use serde_json::Value;

/// Rotates each letter in the input string by 13 positions in the alphabet.
/// Non-alphabetic characters remain unchanged.
/// 
/// # Examples
/// 
/// ```
/// assert_eq!(solve(String::from("Hello, Z!")), String::from("Uryyb, M!"));
/// ```
fn solve(input: serde_json::Value) -> serde_json::Value {
    input.to_string().chars()
        .map(|c| {
            if c.is_alphabetic() {
                let offset = if c.is_uppercase() { 65 } else { 97 };
                (c as u8 + 13 - offset) as char
            } else {
                c
            }
        })
        .collect()
}

fn main() {
    // Example usage
    let input = serde_json::Value::from("Hello, Z!");
    let expected = serde_json::Value::from("Uryyb, M!");
    assert_eq!(solve(input), expected);
}
